package com.snamberi.os;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;import java.text.*;
public class ReminderReceiver extends BroadcastReceiver {
 static final String CHANNEL="snamberi_reminders";static final String PREF="reminders";
 static void channel(Context c){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,"Habit and calendar reminders",NotificationManager.IMPORTANCE_DEFAULT);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
 @Override public void onReceive(Context c,Intent intent){channel(c);String title=intent.getStringExtra("title"),body=intent.getStringExtra("body");if(title==null)return;Intent launch=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(title).setContentText(body==null?"Time for your routine":body).setAutoCancel(true).setContentIntent(pi).build();int id=intent.getIntExtra("id",0);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(id,n);
 long interval=intent.getLongExtra("interval",0);if(interval>0){long next=System.currentTimeMillis()+interval;Calendar cal=Calendar.getInstance();cal.setTimeInMillis(next);String time=intent.getStringExtra("time");if(time!=null){String[] parts=time.split(":");cal.set(Calendar.HOUR_OF_DAY,Integer.parseInt(parts[0]));cal.set(Calendar.MINUTE,Integer.parseInt(parts[1]));cal.set(Calendar.SECOND,0);}schedule(c,id,cal.getTimeInMillis(),title,body,interval,time);}}
 static void schedule(Context c,int id,long when,String title,String body,long interval,String time){Intent i=new Intent(c,ReminderReceiver.class);i.putExtra("title",title);i.putExtra("body",body);i.putExtra("id",id);i.putExtra("interval",interval);i.putExtra("time",time);PendingIntent p=PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.set(AlarmManager.RTC_WAKEUP,when,p);}
 static void scheduleAll(Context c,String json){try{JSONObject data=new JSONObject(json);android.content.SharedPreferences prefs=c.getSharedPreferences(PREF,0);String old=prefs.getString("ids","");AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(String str:old.split(",")){if(str.isEmpty())continue;int id=Integer.parseInt(str);PendingIntent p=PendingIntent.getBroadcast(c,id,new Intent(c,ReminderReceiver.class),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){am.cancel(p);p.cancel();}}
 ArrayList<Integer> ids=new ArrayList<>();JSONObject r=data.optJSONObject("reminders");if(r==null)r=new JSONObject();String[][] defs={{"skinAM","Morning skincare","08:00","127"},{"skinPM","Evening skincare","21:00","127"},{"bedtime","Time to wind down for sleep","22:30","127"},{"basketball","Basketball practice","16:00","42"},{"gym","Gym workout","17:00","84"}};
 int id=1000;for(String[] def:defs){String time=r.optString(def[0],def[2]);if(!time.matches("\\d{2}:\\d{2}"))continue;String[] hm=time.split(":");int hour=Integer.parseInt(hm[0]),minute=Integer.parseInt(hm[1]);if(hour>23||minute>59)continue;String days=def[3];for(int dow=1;dow<=7;dow++){boolean include=days.equals("127")||(days.equals("42")&&(dow==Calendar.MONDAY||dow==Calendar.WEDNESDAY||dow==Calendar.FRIDAY))||(days.equals("84")&&(dow==Calendar.TUESDAY||dow==Calendar.THURSDAY||dow==Calendar.SATURDAY));if(!include)continue;Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,hour);cal.set(Calendar.MINUTE,minute);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);while(cal.get(Calendar.DAY_OF_WEEK)!=dow||cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);schedule(c,id,cal.getTimeInMillis(),def[1],"Open Snamberi OS to track your progress",7L*24*3600000,time);ids.add(id++);}}
 JSONArray events=data.optJSONArray("events");if(events!=null)for(int j=0;j<events.length();j++){JSONObject e=events.optJSONObject(j);if(e==null||e.optBoolean("done"))continue;String date=e.optString("date"),time=e.optString("time");if(!date.matches("\\d{4}-\\d{2}-\\d{2}")||!time.matches("\\d{2}:\\d{2}"))continue;try{SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);fmt.setLenient(false);long when=fmt.parse(date+" "+time).getTime();if(when>System.currentTimeMillis()){schedule(c,id,when,e.optString("title","Calendar event"),"Scheduled activity starts now",0,null);ids.add(id++);}}catch(Exception ignored){}}
 StringBuilder sb=new StringBuilder();for(Integer n:ids)sb.append(n).append(',');prefs.edit().putString("ids",sb.toString()).apply();}catch(Exception e){android.util.Log.e("Snamberi","Failed to schedule",e);}}
}
